def es_anomalo(intentos_fallidos, hora):
    if intentos_fallidos >= 5:
        return True
    if hora < 6 or hora > 22:
        return True
    return False

eventos = [
    {"usuario": "ana", "intentos_fallidos": 2, "hora": 14},
    {"usuario": "root", "intentos_fallidos": 7, "hora": 15},
    {"usuario": "carlos", "intentos_fallidos": 0, "hora": 3},
]

for e in eventos:
    print(f"{e['usuario']}: anomalo={es_anomalo(e['intentos_fallidos'], e['hora'])}")
